package com.zentro.dispatchcourier.dispatch.coordination;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.util.*;
import java.time.Instant;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import com.zentro.dispatchcourier.dispatch.service.ParcelSource;
import com.zentro.dispatchcourier.dispatch.repository.AssignmentRepository;
import com.zentro.dispatchcourier.courier.service.IdentityCourierClient;
@Testcontainers
class AssignmentCoordinationPostgresTest {
 @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:16-alpine");
 static JdbcTemplate jdbc;static DataSourceTransactionManager manager;
 AssignmentOperationStore store;ParcelClaimClient claims;CoordinatedParcelSource source;AssignmentRepository assignments;UUID parcel;JwtDecoder decoder;
 @BeforeAll static void database(){var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());manager=new DataSourceTransactionManager(ds);jdbc=new JdbcTemplate(ds);org.flywaydb.core.Flyway.configure().dataSource(ds).schemas("dispatch").defaultSchema("dispatch").load().migrate();}
 @BeforeEach void setup(){jdbc.execute("TRUNCATE dispatch.assignment_operation,dispatch.proof_of_delivery,dispatch.delivery_assignment,dispatch.assignment_audit,dispatch.outbox_event");store=spy(new AssignmentOperationStore(jdbc,manager));claims=mock(ParcelClaimClient.class);decoder=mock(JwtDecoder.class);when(decoder.decode("synthetic-token")).thenReturn(Jwt.withTokenValue("synthetic-token").header("alg","synthetic").subject("dispatcher").build());source=new CoordinatedParcelSource(store,claims,decoder);assignments=new AssignmentRepository(jdbc,manager);parcel=UUID.randomUUID();when(claims.acquire(any(),anyString())).thenAnswer(i->{AssignmentOperationStore.Operation op=i.getArgument(0);return new ParcelClaimClient.Claim(op.operationId(),op.parcelId(),"HELD",new ParcelSource.Parcel(op.parcelId(),"SYNTHETIC","Area A","Area B",Instant.now()));});}
 AssignmentRepository.Assignment insert(){return assignments.insert(parcel,new IdentityCourierClient.Courier(UUID.randomUUID(),UUID.randomUUID(),"Synthetic",true,"ACTIVE"),"dispatcher");}
 int count(String table){return jdbc.queryForObject("SELECT count(*) FROM dispatch."+table,Integer.class);}
 @Test void assignmentOutcomeAuditAndEventCommitTogether(){var result=source.withEligibleParcel(parcel,"synthetic-token",p->insert());assertThat(result.parcelId()).isEqualTo(parcel);assertThat(count("delivery_assignment")).isEqualTo(1);assertThat(count("assignment_audit")).isEqualTo(1);assertThat(count("outbox_event")).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT state FROM dispatch.assignment_operation",String.class)).isEqualTo("COMMITTED");verify(claims).finish(argThat(o->o.state().equals("COMMITTED")),eq("synthetic-token"));}
 @Test void rollbackReleasesOnlyAfterDurableAbort(){assertThatThrownBy(()->source.withEligibleParcel(parcel,"synthetic-token",p->{insert();throw new IllegalStateException("synthetic rollback");})).isInstanceOf(IllegalStateException.class);assertThat(count("delivery_assignment")).isZero();assertThat(count("assignment_audit")).isZero();assertThat(count("outbox_event")).isZero();verify(claims).finish(argThat(o->o.state().equals("ABORTED")),eq("synthetic-token"));}
 @Test void networkAcquireTimeoutNeverRunsAssignmentAndReconcilesFencedAbort(){doThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE)).when(claims).acquire(any(),anyString());assertThatThrownBy(()->source.withEligibleParcel(parcel,"synthetic-token",p->insert())).isInstanceOf(ResponseStatusException.class);assertThat(count("delivery_assignment")).isZero();verify(claims).finish(argThat(o->o.state().equals("ABORTED")),eq("synthetic-token"));}
 @Test void finalizationFailureKeepsCommitAndLaterRetryConfirms(){doThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE)).when(claims).finish(any(),anyString());assertThatThrownBy(()->source.withEligibleParcel(parcel,"synthetic-token",p->insert())).isInstanceOf(ResponseStatusException.class);var op=store.unsettled(parcel).orElseThrow();assertThat(op.state()).isEqualTo("COMMITTED");assertThat(count("delivery_assignment")).isEqualTo(1);reset(claims);source.reconcile(op.operationId(),"synthetic-token");verify(claims).finish(argThat(o->o.state().equals("COMMITTED")),eq("synthetic-token"));assertThat(store.unsettled(parcel)).isEmpty();}
 @Test void commitAcknowledgementLossNeverReleasesCommittedAssignment(){doAnswer(i->{Object result=i.callRealMethod();throw new org.springframework.dao.RecoverableDataAccessException("synthetic acknowledgement loss");}).when(store).commit(any(),any());assertThatThrownBy(()->source.withEligibleParcel(parcel,"synthetic-token",p->insert())).isInstanceOf(org.springframework.dao.RecoverableDataAccessException.class);assertThat(count("delivery_assignment")).isEqualTo(1);verify(claims).finish(argThat(o->o.state().equals("COMMITTED")),eq("synthetic-token"));verify(claims,never()).finish(argThat(o->o.state().equals("ABORTED")),anyString());}
 @Test void crashedPreparedOperationIsFencedBeforeRelease(){var op=store.prepare(parcel,"dispatcher","ASSIGN");source.reconcile(op.operationId(),"synthetic-token");assertThatThrownBy(()->store.commit(op.operationId(),()->insert())).isInstanceOf(ResponseStatusException.class);assertThat(count("delivery_assignment")).isZero();}
 @Test void recoveryWaitsForInflightTransactionBeforeDeciding() throws Exception {var op=store.prepare(parcel,"dispatcher","ASSIGN");var entered=new CountDownLatch(1);var finish=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var commit=pool.submit(()->store.commit(op.operationId(),()->{entered.countDown();try{finish.await(5,TimeUnit.SECONDS);}catch(InterruptedException e){throw new RuntimeException(e);}return insert();}));assertThat(entered.await(5,TimeUnit.SECONDS)).isTrue();var recovery=pool.submit(()->source.reconcile(op.operationId(),"synthetic-token"));Thread.sleep(100);assertThat(recovery.isDone()).isFalse();finish.countDown();commit.get(10,TimeUnit.SECONDS);assertThat(recovery.get(10,TimeUnit.SECONDS).state()).isEqualTo("COMMITTED");}}
 @Test void unknownStorageOutcomeCannotReleaseClaim(){var op=store.prepare(parcel,"dispatcher","ASSIGN");doThrow(new org.springframework.dao.DataAccessResourceFailureException("synthetic storage failure")).when(store).abortIfPrepared(op.operationId());assertThatThrownBy(()->source.reconcile(op.operationId(),"synthetic-token")).isInstanceOf(org.springframework.dao.DataAccessResourceFailureException.class);verifyNoInteractions(claims);}
 @Test void duplicatePreparedOperationsCannotCoexist(){store.prepare(parcel,"dispatcher","ASSIGN");assertThatThrownBy(()->store.prepare(parcel,"dispatcher","ASSIGN")).isInstanceOf(ResponseStatusException.class);}
 @Test void reassignmentAndCancellationRetainAuditAndEvents(){insert();int before=count("outbox_event");source.withAssignedParcel(parcel,"synthetic-token",p->assignments.reassign(parcel,new IdentityCourierClient.Courier(UUID.randomUUID(),UUID.randomUUID(),"Synthetic",true,"ACTIVE"),"dispatcher"));source.withAssignedParcel(parcel,"synthetic-token",p->{assignments.cancel(parcel,"dispatcher");return null;});assertThat(count("delivery_assignment")).isZero();assertThat(count("assignment_audit")).isEqualTo(3);assertThat(count("outbox_event")).isEqualTo(before+2);}
 @Test void foreignDispatcherCannotReconcile(){var op=store.prepare(parcel,"owner-A","ASSIGN");assertThatThrownBy(()->source.reconcile(op.operationId(),"synthetic-token")).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(claims);}
}
